when.expression:
#[if(vars.vExplicitReprocessing default false as Boolean) true
else ((Mule::p('reprocess') default true) 
	and (vars.vReprocess default true) 
	and (vars.vErrorPayload.errorCategory == "TECHNICAL")
	and !((Mule::p('errorType.skipReprocessErrors') splitBy  ",") contains vars.vErrorPayload.errorType)
) as Boolean]

#[if(vars.vExplicitReprocessing default false as Boolean) true
else ((Mule::p('reprocess') default true) 
	and (vars.vReprocess default true) 
	and (vars.vErrorPayload.errorCategory == "TECHNICAL")
	and !((Mule::p('errorType.skipReprocessErrors') splitBy  ",") contains vars.vErrorPayload.errorType)
) as Boolean]

ee:variables.ee:set-variable:
%dw 2.0
import * from statusCode
output application/json
---
vars.httpStatus default (
	if((!isEmpty(error.errorMessage.attributes.statusCode)) and (error.errorMessage.attributes.statusCode != 500)) 
		error.errorMessage.attributes.statusCode
	else if (!isEmpty(error.attributes.statusCode)) 
		error.attributes.statusCode
	else generateHttpStatusCode((error.errorType.namespace default "") ++ ":" ++ (error.errorType.identifier default "")))

%dw 2.0
output application/json
import firstWith from dw::core::Arrays
// Function to convert data type to string
fun toStringFormat(value, def="") = do {
	var message = if ( !isEmpty(value) ) value else def default ""
	---
	typeOf(message) match {
		case "String" -> message
        case "Number" -> message as String
        case "Binary" -> read(message, "text/plain")  
        else -> write(message, "application/java")
	}
}
var business = Mule::p('errorType.business') splitBy  ","

var technical = Mule::p('errorType.technical') splitBy  ","

fun errorCategory(errorType) = if (business contains(errorType)) "BUSINESS"
	else if (technical contains(errorType)) "TECHNICAL"
	else "TECHNICAL"

---
// This condition handles COMPOSITE_ROUTING and RETRY_EXHAUSTED errorType
if ( ['COMPOSITE_ROUTING', 'RETRY_EXHAUSTED'] contains error.errorType.identifier ) (do {
	var getErrorDescription = toStringFormat(error.description)
	var getSuppressedErrorMessage =  do {
		var message = [error.childErrors..errorMessage.payload, error.suppressedErrors..errorMessage.payload] firstWith(!isEmpty($))
		---
		if ( message is Array ) toStringFormat(message map (toStringFormat($)) distinctBy $)
	    else toStringFormat(message)
	}
	var errorType = if ( !isEmpty(error.suppressedErrors) ) error.suppressedErrors..namespace[0] ++ ":" ++ error.suppressedErrors..identifier[0]
					else if ( !isEmpty(error.childErrors) ) error.childErrors..errorType map ($.namespace ++ ":" ++ $.identifier) distinctBy ($) joinBy ", "
					else (error.errorType.namespace ++ ":" ++ error.errorType.identifier)
	---
	{
		"transactionId": vars.vApi_Header.correlationId default correlationId,
		"statusCode": vars.httpStatus,
		"errorType": errorType default ((error.errorType.namespace default "") ++ ":" ++ (error.errorType.identifier default "")),
		"errorCategory": errorCategory((error.errorType.namespace default "") ++ ":" ++ (error.errorType.identifier default "")),
		"errorMessage": error.description,
		"errorDetails": ((([getSuppressedErrorMessage, getErrorDescription] filter !isEmpty($)) distinctBy $) joinBy " | ") default "Unknown",
		"apiName": Mule::p('api.name') default Mule::p('app.name'),
		"method": vars.vApi_Header.x_api_flow default ""
	}
})

// This if else condition handles any propagated error from calling API's and error response should not be in Binary format
//else if ( (!isEmpty(error.errorMessage.payload)) and (typeOf(error.errorMessage.payload) as String != "Binary") and (typeOf(error.errorMessage.payload) as String != "String") ) 
else if ( (!isEmpty(error.errorMessage.payload)) and (typeOf(error.errorMessage.payload) as String == "Object") ) 
{
	"transactionId": error.errorMessage.payload.transactionId default vars.vApi_Header.correlationId default correlationId,
	"statusCode": error.errorMessage.payload.statusCode default vars.httpStatus,
	"errorType": error.errorMessage.payload.errorType default ((error.errorType.namespace default "") ++ ":" ++ (error.errorType.identifier default "")),
	"errorCategory": error.errorMessage.payload.errorCategory default errorCategory((error.errorType.namespace default "") ++ ":" ++ (error.errorType.identifier default "")),
	"errorMessage": error.errorMessage.payload.errorMessage default error.description,
	"errorDetails": error.errorMessage.payload.errorDetails default error.detailedDescription,
	"apiName": error.errorMessage.payload.apiName default Mule::p('api.name') default Mule::p('app.name'),
	"method": error.errorMessage.payload.method default vars.vApi_Header.x_api_flow,
	"S4_HANA": if ( !isEmpty(error.errorMessage.payload.S4_HANA) ) error.errorMessage.payload.S4_HANA 
		else if ( (typeOf(error.errorMessage.payload.error) as String == "Object") and !isEmpty(error.errorMessage.payload.error.message) ) {
			"error_code": error.errorMessage.payload.error.innererror.errordetails[0].code default error.errorMessage.payload.error.code,
			"error": error.errorMessage.payload.error.innererror.errordetails[0].message default error.errorMessage.payload.error.message,
			"error_detail": {
				"component_id": error.errorMessage.payload.error.innererror.application.component_id default "",
				"service_id": error.errorMessage.payload.error.innererror.application.service_id default "",
				"service_version": error.errorMessage.payload.error.innererror.application.service_version default "",
				"transaction_id": error.errorMessage.payload.error.innererror.transactionid default "",
				"target": error.errorMessage.payload.error.innererror.errordetails.target default ""
			}
		}
	else null
}

// If any error are not handled in above two conditions will be handled in else (default)
else {
	"transactionId": vars.vApi_Header.correlationId default correlationId,
	"statusCode": vars.httpStatus,
	"errorType": (error.errorType.namespace default "") ++ ":" ++ (error.errorType.identifier default ""),
	"errorCategory": errorCategory((error.errorType.namespace default "") ++ ":" ++ (error.errorType.identifier default "")),
	"errorMessage": error.description,
	"errorDetails": error.detailedDescription,
	"apiName": Mule::p('api.name') default Mule::p('app.name'),
	"method": vars.vApi_Header.x_api_flow default ""
}

%dw 2.0
output application/json
---
if(!isEmpty(vars.vkafkaDetails)) vars.vkafkaDetails
else {
	"errorTopic": if(!isEmpty(vars.vKafkaErrorTopic)) vars.vKafkaErrorTopic else Mule::p('kafka.errQueue'),
	"dlqTopic": if(!isEmpty(vars.vKafkaDLQTopic)) vars.vKafkaDLQTopic else Mule::p('kafka.dlq'), 
	"header": if(!isEmpty(vars.vKafkaHeader)) vars.vKafkaHeader else {
		"x-correlation-id": vars.vApi_Header.correlationId,
		"x-message-id": vars.vApi_Header.businessObjectKey,
		"businessObjectKey": vars.vApi_Header.businessObjectKey
	}
}
